#!/usr/bin/env python3

"""
RoboMaster 哨兵导航与决策系统
第 7 课：RobotState 机器人状态

本课目标：

建立一个统一的 RobotState，
用来保存机器人当前的各种状态。

目前包含：

    health       机器人血量
    x            当前 X 坐标
    y            当前 Y 坐标
    yaw          当前朝向
    match_time   比赛时间

目前只有 health 从 ROS2 Topic 获取。

其他数据暂时使用模拟值。

以后会逐渐接入真实数据：

    health
        ↓
    STM32 / 比赛系统

    x / y / yaw
        ↓
    SLAM / 定位 / TF2

    match_time
        ↓
    比赛状态系统
"""


# =====================================================
# 导入 ROS2
# =====================================================

import rclpy

from rclpy.node import Node


# =====================================================
# 导入 ROS2 消息类型
# =====================================================

from std_msgs.msg import Int32


# =====================================================
# RobotState
# =====================================================

class RobotState:

    """
    RobotState：

    保存机器人当前的状态。

    它不是 ROS2 Node。

    它只是一个“数据容器”。

    可以把它理解成：

        机器人当前状态表
    """

    def __init__(self):

        # =================================================
        # 1. 血量
        # =================================================

        # 初始血量暂时设置为 100。
        #
        # 后面会由真实比赛数据更新。

        self.health = 100


        # =================================================
        # 2. X 坐标
        # =================================================

        # 当前暂时使用模拟值 0.0。

        self.x = 0.0


        # =================================================
        # 3. Y 坐标
        # =================================================

        self.y = 0.0


        # =================================================
        # 4. Yaw 朝向
        # =================================================

        # yaw 表示机器人在二维地图中的朝向。

        # 例如：
        #
        # 0       → 朝 X 正方向
        # 1.57    → 大约朝 Y 正方向
        #
        # 这里暂时设置为 0。

        self.yaw = 0.0


        # =================================================
        # 5. 比赛时间
        # =================================================

        # 当前先设置为 0 秒。
        #
        # 下一课我们再让它真正开始变化。

        self.match_time = 0.0


# =====================================================
# RobotStateNode
# =====================================================

class RobotStateNode(Node):

    """
    RobotStateNode：

    真正的 ROS2 节点。

    它负责：

        接收 ROS2 数据
              ↓
        更新 RobotState
              ↓
        输出当前状态
    """

    def __init__(self):

        # =================================================
        # 初始化 ROS2 Node
        # =================================================

        super().__init__("robot_state_node")


        # =================================================
        # 创建 RobotState
        # =================================================

        # 创建一个机器人状态对象。

        self.state = RobotState()


        # =================================================
        # 创建血量 Subscriber
        # =================================================

        self.health_subscription = self.create_subscription(

            Int32,

            "/sentinel/health",

            self.health_callback,

            10
        )


        # =================================================
        # 创建 Timer
        # =================================================

        # 每 1 秒执行一次 print_state()。

        self.timer = self.create_timer(

            1.0,

            self.print_state
        )


        # =================================================
        # 输出启动信息
        # =================================================

        self.get_logger().info(

            "Robot State Node Start!"
        )


    # =====================================================
    # 血量 Callback
    # =====================================================

    def health_callback(self, msg):

        """
        当 /sentinel/health 收到消息时：

            msg.data
                ↓
            self.state.health
        """

        # 把 ROS2 收到的血量，
        # 保存到 RobotState 中。

        self.state.health = msg.data


    # =====================================================
    # 打印当前状态
    # =====================================================

    def print_state(self):

        """
        每秒打印一次当前 RobotState。
        """

        self.get_logger().info(

            f"Health = {self.state.health}"
        )


        self.get_logger().info(

            f"Position = "
            f"X:{self.state.x}, "
            f"Y:{self.state.y}"
        )


        self.get_logger().info(

            f"Yaw = {self.state.yaw}"
        )


        self.get_logger().info(

            f"Match Time = "
            f"{self.state.match_time}"
        )


# =====================================================
# main
# =====================================================

def main(args=None):

    # =================================================
    # 初始化 ROS2
    # =================================================

    rclpy.init(args=args)


    # =================================================
    # 创建 RobotStateNode
    # =================================================

    node = RobotStateNode()


    # =================================================
    # 保持节点运行
    # =================================================

    rclpy.spin(node)


    # =================================================
    # 关闭 ROS2
    # =================================================

    rclpy.shutdown()


# =====================================================
# Python 程序入口
# =====================================================

if __name__ == "__main__":

    main()
